args<-commandArgs(FALSE);root<-dirname(normalizePath(sub('^--file=','',args[grepl('^--file=',args)])))
out<-file.path(root,'outputs');d<-read.csv(file.path(out,'culinary_activity_monthly.csv'));d$date<-as.Date(paste0(d$month,'-15'))
labs<-c('Middle Eastern','National','Mediterranean');colors<-c('#B75A2A','#6B52A3','#007F86')
counts<-read.csv(file.path(out,'culinary_activity_prepost.csv'))
draw<-function(){par(mar=c(4,5,4,1),oma=c(7,0,3,0),family='sans')
 plot(range(as.Date(c('2015-12-01','2017-04-30'))),c(0,19),type='n',xlab='',ylab='Restaurants with at least one review',axes=FALSE)
 axis(2,at=seq(0,16,2),las=1);axis.Date(1,at=sort(unique(d$date)),format='%b\n%Y',cex.axis=.8);abline(h=seq(0,16,2),col='gray92')
 abline(v=as.Date('2017-01-24'),lty=3,col='gray35');abline(v=as.Date('2017-01-27'),lty=2,col='gray35')
 for(i in 1:3){s<-d[d$label==labs[i],];lines(s$date,s$restaurants,type='o',pch=16,cex=.8,lwd=2,col=colors[i])}
 legend('topleft',legend=paste(c('Literal Middle Eastern','National labels','Mediterranean'),sprintf('(fixed cohort n = %s)',counts$cohort_restaurants)),col=colors,lty=1,pch=16,ncol=1,bty='n',cex=.9)
 title('Monthly review activity in the culinary-comparable sample',line=2,cex.main=1.2)
 mtext('Fixed 36 restaurants in seven Trump-majority counties; American restaurants are not in this sample',3,line=.5,cex=.9)
 mtext('Eligibility: pre-Nov 8, 2016 food evidence + an opposite-positioning culinary peer in the same county;',1,outer=TRUE,line=.6,cex=.9)
 mtext('at least one rating in Nov 14, 2016-Apr 9, 2017. No requirement for reviews in both ban windows.',1,outer=TRUE,line=1.9,cex=.9)
 mtext('Monthly count = fixed-cohort restaurants with at least one review; cohort membership does not change.',1,outer=TRUE,line=3.2,cex=.9)
 mtext('Jan 24 coverage (dotted); Jan 27 implementation (dashed). January includes both pre- and post-ban days.',1,outer=TRUE,line=4.5,cex=.85)
 mtext('Retrospectively selected cohort: early activity is descriptive, not an unbiased sample of restaurants operating then.',1,outer=TRUE,line=5.8,cex=.85)
}
png(file.path(out,'culinary_activity.png'),width=1900,height=1200,res=150);draw();dev.off()
pdf(file.path(out,'culinary_activity.pdf'),width=1900/150,height=8);draw();dev.off()
